import{_ as n,o as s,c as t,a6 as e}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"架构设计与技术选型","description":"先想清楚为什么做组件库、用什么技术栈，再决定目录结构。","frontmatter":{"title":"架构设计与技术选型","description":"先想清楚为什么做组件库、用什么技术栈，再决定目录结构。"},"headers":[],"relativePath":"manual/engineering-practice/vue-component-library/architecture.md","filePath":"manual/engineering-practice/vue-component-library/architecture.md"}'),r={name:"manual/engineering-practice/vue-component-library/architecture.md"};function p(l,a,d,i,o,c){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="架构设计与技术选型" tabindex="-1">架构设计与技术选型 <a class="header-anchor" href="#架构设计与技术选型" aria-label="Permalink to &quot;架构设计与技术选型&quot;">​</a></h1><blockquote><p>开始编码之前，先想清楚「为什么」和「怎么选」。</p></blockquote><h2 id="_1-1-为什么做组件库" tabindex="-1">1.1 为什么做组件库？ <a class="header-anchor" href="#_1-1-为什么做组件库" aria-label="Permalink to &quot;1.1 为什么做组件库？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>痛点</th><th>组件库如何解决</th></tr></thead><tbody><tr><td>多项目 UI 风格不统一</td><td>统一视觉规范，一套代码多处复用</td></tr><tr><td>每个项目重复造轮子</td><td>沉淀通用组件，一次维护</td></tr><tr><td>新人上手需要了解业务细节</td><td>组件与业务解耦，独立可测试</td></tr><tr><td>缺少设计系统（Design System）</td><td>组件库是设计系统的代码载体</td></tr></tbody></table><h2 id="_1-2-monorepo-vs-polyrepo" tabindex="-1">1.2 Monorepo vs Polyrepo <a class="header-anchor" href="#_1-2-monorepo-vs-polyrepo" aria-label="Permalink to &quot;1.2 Monorepo vs Polyrepo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Monorepo ✅</th><th>Polyrepo</th></tr></thead><tbody><tr><td>跨包联调</td><td>软链接直接引用</td><td>需要 npm link 或发布到测试源</td></tr><tr><td>依赖管理</td><td>统一一个 lockfile</td><td>每个仓库独立</td></tr><tr><td>版本统一</td><td>Changesets 自动关联</td><td>手动协调多仓库版本</td></tr><tr><td>CI/CD</td><td>一次构建所有包</td><td>需要跨仓库触发</td></tr><tr><td>权限</td><td>粒度较粗</td><td>可按仓库细分</td></tr></tbody></table><p><strong>结论</strong>：组件库这类紧密关联的多包项目 → <strong>Monorepo</strong>。</p><h2 id="_1-3-为什么选-pnpm-workspace" tabindex="-1">1.3 为什么选 pnpm Workspace？ <a class="header-anchor" href="#_1-3-为什么选-pnpm-workspace" aria-label="Permalink to &quot;1.3 为什么选 pnpm Workspace？&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm workspaces    → 最流行，但依赖提升策略较粗犷</span></span>
<span class="line"><span>yarn workspaces   → 也不错，yarn berry (v2+) 配置复杂</span></span>
<span class="line"><span>pnpm workspaces  → 最严格的依赖隔离 + 磁盘空间优化 + 原生 workspace 协议</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>pnpm 的核心优势：</p><ul><li><strong>严格隔离</strong>：每个包只能访问自己声明的依赖，幽灵依赖零容忍</li><li><strong>硬链接存储</strong>：所有项目共用一份 node_modules 实体，磁盘占用极小</li><li><strong>workspace 协议</strong>：<code>@vcl/components</code> 直接指向本地包，联调零成本</li></ul><h2 id="_1-4-推荐技术栈全景" tabindex="-1">1.4 推荐技术栈全景 <a class="header-anchor" href="#_1-4-推荐技术栈全景" aria-label="Permalink to &quot;1.4 推荐技术栈全景&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                 VCL Monorepo                        │</span></span>
<span class="line"><span>│                                                       │</span></span>
<span class="line"><span>│  ┌──────────────┐  ┌──────────────┐  ┌─────────────┐ │</span></span>
<span class="line"><span>│  │   components │  │    docs      │  │  playground │ │</span></span>
<span class="line"><span>│  │   (组件包)    │  │ (VitePress)  │  │  (调试页)    │ │</span></span>
<span class="line"><span>│  └──────┬───────┘  └──────────────┘  └─────────────┘ │</span></span>
<span class="line"><span>│         │                                              │</span></span>
<span class="line"><span>│  ┌──────▼──────────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │  Vue 3.5 + TypeScript 5 + Vite 8               │  │</span></span>
<span class="line"><span>│  │  Storybook 10 · Vitest 5 · vite-plugin-dts 5    │  │</span></span>
<span class="line"><span>│  │  ESLint 9 · Prettier 3 · Stylelint 16           │  │</span></span>
<span class="line"><span>│  │  Changesets 3 (版本管理)                         │  │</span></span>
<span class="line"><span>│  └─────────────────────────────────────────────────┘  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h3 id="各工具的角色" tabindex="-1">各工具的角色 <a class="header-anchor" href="#各工具的角色" aria-label="Permalink to &quot;各工具的角色&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>版本</th><th>做什么</th><th>为什么选它</th></tr></thead><tbody><tr><td>Vue 3</td><td>^3.5</td><td>组件运行时</td><td>Composition API + <code>&lt;script setup&gt;</code> 是现代标准</td></tr><tr><td>TypeScript</td><td>^5.7</td><td>类型安全</td><td>组件库的类型质量直接决定用户体验</td></tr><tr><td>Vite</td><td>^8</td><td>构建 &amp; 开发服务器</td><td>Library Mode 零配置即可产出 ESM/CJS</td></tr><tr><td>vite-plugin-dts</td><td>^5</td><td>自动生成 .d.ts</td><td>省去单独跑 vue-tsc --emitDeclarationOnly</td></tr><tr><td>Storybook</td><td>^10</td><td>组件开发环境 + 预览</td><td>每个组件独立可看，支持 controls/knobs</td></tr><tr><td>Vitest</td><td>^5</td><td>单元测试</td><td>与 Vite 共用底层，极速，Vue Test Utils 官方推荐</td></tr><tr><td>VitePress</td><td>^1.5</td><td>文档站</td><td>Vite 同生态，Markdown + Vue 组件灵活组合</td></tr><tr><td>Changesets</td><td>^3</td><td>版本管理 &amp; 发布</td><td>monorepo 版本号联动 + CHANGELOG 自动生成</td></tr></tbody></table><h2 id="_1-5-各包职责划分" tabindex="-1">1.5 各包职责划分 <a class="header-anchor" href="#_1-5-各包职责划分" aria-label="Permalink to &quot;1.5 各包职责划分&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/</span></span>
<span class="line"><span>├── components/   ← 核心组件库（对外发布到 npm）</span></span>
<span class="line"><span>├── docs/         ← 文档站（内部或部署到 Vercel/Netlify）</span></span>
<span class="line"><span>└── playground/   ← 可选：不依赖 Storybook 的最小调试页</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="包之间的依赖方向" tabindex="-1">包之间的依赖方向 <a class="header-anchor" href="#包之间的依赖方向" aria-label="Permalink to &quot;包之间的依赖方向&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>components ← docs          (文档站引用组件进行实时演示)</span></span>
<span class="line"><span>components ← playground    (playground 引用组件进行联调)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>关键原则</strong>：<code>components</code> 不能依赖 <code>docs</code> 或 <code>playground</code>，单向依赖。</p><h2 id="_1-6-设计原则速查" tabindex="-1">1.6 设计原则速查 <a class="header-anchor" href="#_1-6-设计原则速查" aria-label="Permalink to &quot;1.6 设计原则速查&quot;">​</a></h2><p>在动手写第一个组件之前，牢记以下原则：</p><ol><li><strong>单一职责</strong>：一个组件只做一件事（Button 只管按钮，不管表单校验）</li><li><strong>语义化命名</strong>：Props / Emits / 组件名让人一看就懂</li><li><strong>类型优先</strong>：每个 Props 都要有明确的 TS 类型</li><li><strong>可组合</strong>：通过 slot / 嵌套组件让组件可灵活组装</li><li><strong>无障碍（a11y）</strong>：遵循 WAI-ARIA 规范，提供键盘导航</li><li><strong>主题化</strong>：样式基于 CSS Variables，支持运行时换肤</li></ol>`,23)])])}const u=n(r,[["render",p]]);export{h as __pageData,u as default};
